class Solution {
public:
    vector<int> arrayChange(vector<int>& nums, vector<vector<int>>& operations) {
        int pos[1000001];
        memset(pos, -1, sizeof(pos));
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            pos[nums[i]] = i;
        }
        for (auto& op : operations) {
            int oldVal = op[0];
            int newVal = op[1];
            int idx = pos[oldVal];
            nums[idx] = newVal;
            pos[newVal] = idx;
            pos[oldVal] = -1;
        }
        return nums;
    }
};
